// Hub · M4 AI layer request: DeepSeek judges the statistical anomaly candidates, adjusts interest scores for the
// top contacts (with a reason each) and writes the narrative (incl. stage movement over 7/14/30 days).

const m = $json;
const compact = {
  event: m.event, kpis: m.kpis, funnel: m.funnel,
  lifecycle_stage_entries: Object.fromEntries(m.movement.map(r => [`last_${r.window}_days`, { new_leads: r.lead, new_mqls: r.marketingqualifiedlead, new_sqls: r.salesqualifiedlead }])),
  engagement_today: m.engagement_today, engagement_prev_daily_avg: m.engagement_prev_avg,
  anomaly_candidates: m.candidates,
  top_accounts: m.accounts.slice(0, 6).map(a => ({ name: a.name, score: a.score, contacts: a.contacts, functions: a.functions, buying_committee: a.committee,
    members: a.members.map(x => `${x.name} (${x.title || x.function}, ${x.seniority}, tier ${x.tier}, score ${x.score}, ${x.stage})`) })),
  top_contacts: m.top_contacts.map(p => ({ id: p.id, name: p.name, title: p.title, company: p.company, tier: p.tier, stage: p.stage,
    attendance: p.attendance, minutes: p.minutes, questions: p.questions, base_score: p.base_score, signals: p.signals })),
};

const system = `You are a revenue-operations analyst reviewing post-webinar lead data for an enterprise HR-tech company.
Use ONLY the numbers provided. Return ONLY valid JSON (inside string values never use the " character; use ' instead):
{
 "headline": "one sentence, the single most important takeaway, max 20 words",
 "narrative": "5-6 sentences for a sales leader: conversion, lifecycle stage movement over the last 7, 14 and 30 days (use lifecycle_stage_entries exactly: e.g. 'in the last 7 days X new leads, Y new MQLs and Z new SQLs'), where intent is concentrated, and what to do next",
 "anomalies": [ { "title": "max 8 words", "severity": "high | medium | low", "type": "account_spike | silent_high_fit | no_show_high_intent | other",
                  "explanation": "1-2 sentences citing the numbers", "who": "account or contact", "action": "one concrete next step for the SDR" } ],
 "score_adjustments": [ { "id": "contact id", "delta": "integer from -15 to 15", "reason": "max 18 words, cites the signal" } ]
}
Rules:
- anomalies: judge each candidate; keep the ones that matter, order by severity. ONE anomaly per person or account: if a spike is driven by one person who is also a candidate, report it once (as that person's anomaly). You may add at most one 'other' anomaly only if the numbers clearly show it.
- score_adjustments: one entry per top contact. Raise for buying signals (demo request, pricing views, several people from one account), lower for fading interest or poor fit. The base score is a formula; you add judgement.
- Never invent people, accounts or numbers.`;

return [{ json: { metrics: m, request_body: {
  model: 'deepseek-v4-pro', thinking: { type: 'disabled' }, temperature: 0.3, max_tokens: 3000, response_format: { type: 'json_object' },
  messages: [{ role: 'system', content: system }, { role: 'user', content: JSON.stringify(compact) }],
} } }];

// Tolerant JSON parse of a DeepSeek reply: strips ``` fences and repairs the two common breakages
// (raw line breaks and stray double quotes inside string values) with a small character scanner.
const parseAI = (resp, what) => {
  const c = resp && resp.choices && resp.choices[0];
  if (!c) throw new Error(`${what}: DeepSeek returned no answer: ${JSON.stringify(resp).slice(0, 300)}`);
  const t = String((c.message && c.message.content) || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
  const raw = t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1);
  try { return JSON.parse(raw); } catch (e1) {}
  // common LLM slips: bare hashtags in arrays, trailing commas
  const raw2 = raw.replace(/([\[,]\s*)(#[A-Za-z0-9_]+)"?(?=\s*[,\]])/g, '$1"$2"')   // bare hashtags
    .replace(/,(\s*[}\]])/g, '$1');                                                    // trailing commas
  try { return JSON.parse(raw2); } catch (e2) {}
  let out = '', inStr = false;
  for (let i = 0; i < raw2.length; i++) {
    const ch = raw2[i];
    if (!inStr) { out += ch; if (ch === '"') inStr = true; continue; }
    if (ch === '\\') { out += ch + (raw2[i + 1] || ''); i++; continue; }
    if (ch === '\n') { out += '\\n'; continue; }
    if (ch === '\r' || ch === '\t') { out += ch === '\t' ? '\\t' : ''; continue; }
    if (ch === '"') {
      let j = i + 1; while (j < raw2.length && /\s/.test(raw2[j])) j++;
      if (j >= raw2.length || ',}]:'.includes(raw2[j])) { out += ch; inStr = false; } else out += '\\"';
      continue;
    }
    out += ch;
  }
  try { return JSON.parse(out); }
  catch (e) { throw new Error(`${what}: invalid JSON (finish_reason=${c.finish_reason}, ${t.length} chars). Starts: ${t.slice(0, 160)}`); }
};

// Hub · M4: apply the AI layer: validated score adjustments (clamped to ±15), anomalies, narrative.
// A number guard flags any number in the narrative that isn't in the metrics.
const m = $('Build AI prompt').first().json.metrics;
let ai = {}, aiError = '';
try { ai = parseAI($json, 'M4 analysis'); } catch (e) { aiError = e.message.slice(0, 200); }

const adj = {};
(Array.isArray(ai.score_adjustments) ? ai.score_adjustments : []).forEach(a => {
  const d = Math.max(-15, Math.min(15, Math.round(Number(a.delta) || 0)));
  if (a.id) adj[String(a.id)] = { delta: d, reason: String(a.reason || '').slice(0, 160) };
});
const top_contacts = m.top_contacts.map(p => {
  const a = adj[p.id] || { delta: 0, reason: '' };
  return { ...p, ai_delta: a.delta, ai_reason: a.reason, interest_score: Math.max(0, Math.min(100, p.base_score + a.delta)) };
}).sort((x, y) => y.interest_score - x.interest_score);

const known = new Set(JSON.stringify(m).match(/\d+(\.\d+)?/g) || []);
const narrative = String(ai.narrative || '');
const unknownNumbers = (narrative.match(/\d+(\.\d+)?/g) || []).filter(n => !known.has(n) && !['7', '14', '30'].includes(n));
const sev = { high: 0, medium: 1, low: 2 };
const anomalies = (Array.isArray(ai.anomalies) ? ai.anomalies : []).filter(a => a && a.title)
  .sort((a, b) => (sev[a.severity] ?? 3) - (sev[b.severity] ?? 3));

return [{ json: {
  generated_at: new Date().toISOString(), model: 'deepseek-v4-pro',
  headline: ai.headline || '', narrative, anomalies, top_contacts,
  checks: { unknown_numbers_in_narrative: unknownNumbers, ai_error: aiError, adjustments_applied: Object.keys(adj).length },
} }];

// Hub · M1 page data: completeness before vs after, dedupe decisions, tiers, routing, SDR handoff, CSV rows.

const FIELDS = ['firstname', 'lastname', 'email', 'jobtitle', 'company', 'country', 'job_function', 'seniority',
  'company_industry', 'company_size_band', 'icp_tier', 'region', 'hubspot_owner_id', 'lifecyclestage'];
const LABEL = { firstname: 'First name', lastname: 'Last name', email: 'Email', jobtitle: 'Job title', company: 'Company',
  country: 'Country', job_function: 'Job function', seniority: 'Seniority', company_industry: 'Industry',
  company_size_band: 'Company size', icp_tier: 'ICP tier', region: 'Region', hubspot_owner_id: 'Owner', lifecyclestage: 'Lifecycle stage' };
const OWNER = { '169348475': 'Neha · Senior SDR', '169348477': 'Priya · India SDR', '169348476': 'Aman · SEA/MEA SDR', '100973776': 'Rahul · speakers' };
const has = v => v !== undefined && v !== null && v !== '' && v !== 'Unknown';
const parse = (s, fb) => { try { return JSON.parse(s || ''); } catch (e) { return fb; } };

const contacts = $input.all().flatMap(i => i.json.results || []).map(r => ({ id: r.id, ...r.properties }));
const n = contacts.length || 1;
const fields = FIELDS.map(f => ({
  field: LABEL[f],
  before: Math.round(100 * contacts.filter(c => !parse(c.fields_missing_before, FIELDS).includes(f)).length / n),
  after: Math.round(100 * contacts.filter(c => has(c[f])).length / n),
}));
const avg = k => Math.round(fields.reduce((s, r) => s + r[k], 0) / fields.length);
const count = (k, v) => contacts.filter(c => c[k] === v).length;
const scored = contacts.filter(c => c.event_attendance_status !== 'speaker');
const owners = {};
contacts.forEach(c => { const o = OWNER[c.hubspot_owner_id] || 'Unassigned'; owners[o] = (owners[o] || 0) + 1; });
const regions = {};
scored.forEach(c => { regions[c.region || 'row'] = (regions[c.region || 'row'] || 0) + 1; });
const person = c => ({ id: c.id, name: `${c.firstname || ''} ${c.lastname || ''}`.trim(), title: c.jobtitle, company: c.company,
  function: c.job_function, seniority: c.seniority, industry: c.company_industry, size: c.company_size_band, country: c.country,
  tier: (c.icp_tier || '').toUpperCase(), score: Number(c.icp_score || 0), reason: (c.icp_reason || '').replace(/^[ABC] \([^)]*\)\.\s*/, ''),
  owner: OWNER[c.hubspot_owner_id] || '', stage: c.lifecyclestage, dedupe: c.dedupe_status, dedupe_reason: c.dedupe_reason,
  inferred: parse(c.inferred_fields, []).length, source: c.enrichment_source });

return [{ json: {
  generated_at: new Date().toISOString(),
  kpis: { contacts: contacts.length, before: avg('before'), after: avg('after'), merged: count('dedupe_status', 'merged'),
          review: count('dedupe_status', 'needs_review'), tier_a: count('icp_tier', 'a'), tier_b: count('icp_tier', 'b'), tier_c: count('icp_tier', 'c'),
          mqls: contacts.filter(c => ['marketingqualifiedlead', 'salesqualifiedlead'].includes(c.lifecyclestage)).length,
          inferred_values: contacts.reduce((s, c) => s + parse(c.inferred_fields, []).length, 0) },
  fields, owners, regions,
  handoff: scored.filter(c => ['marketingqualifiedlead', 'salesqualifiedlead'].includes(c.lifecyclestage) || c.icp_tier === 'a')
    .sort((a, b) => Number(b.icp_score) - Number(a.icp_score)).map(person),
  dedupe: contacts.filter(c => ['merged', 'needs_review'].includes(c.dedupe_status)).map(person),
  rows: contacts.map(person),
} }];

// Hub · M2 page data: the latest post-event send (3 segment emails) with HubSpot stats, subject variants and UTMs.

const EVENT = 'Darwinbox Cortex and the AI-Native Era of HCM';
const emails = ($('M2 emails').first().json.results || [])
  .filter(e => String(e.name || '').startsWith(EVENT.slice(0, 40)) && e.state !== 'DRAFT' && / · m2-\d+$/.test(e.name || ''));
// latest run id among sent emails
const runs = [...new Set(emails.map(e => e.name.split(' · ').pop()))].sort();
const run = runs[runs.length - 1];
const latest = emails.filter(e => e.name.endsWith(run));
const contacts = $input.all().flatMap(i => i.json.results || []).map(r => r.properties);
const SEG = { 'Attendees: thank-you': 'attendee', 'No-shows: catch-up': 'no_show', 'Speakers: thank-you': 'speaker' };

const segments = latest.map(e => {
  const label = e.name.split(' · ')[1];
  const seg = SEG[label];
  const c = (e.stats && e.stats.counters) || {};
  const mine = contacts.filter(x => String(x.postevent_email_variant || '').startsWith(seg + '_'));
  const subjects = {};
  mine.forEach(x => { const v = x.postevent_email_variant.split('_')[seg === 'no_show' ? 2 : 1]; subjects[v] = subjects[v] || { variant: v, subject: x.pe_subject, contacts: 0 }; subjects[v].contacts++; });
  const personas = {};
  mine.forEach(x => { const p = x.postevent_email_variant.split('_').slice(seg === 'no_show' ? 3 : 2).join('_'); personas[p] = (personas[p] || 0) + 1; });
  return { label, segment: seg, email_id: e.id, state: e.state, published: e.publishDate,
    recipients: mine.length, sent: c.sent || 0, delivered: c.delivered || 0, opens: c.open || 0, clicks: c.click || 0,
    dropped: c.dropped || 0, bounced: c.bounce || 0,
    subjects: Object.values(subjects).sort((a, b) => a.variant.localeCompare(b.variant)), personas,
    sample_opening_line: (mine.find(x => x.pe_opening_line) || {}).pe_opening_line || '' };
}).sort((a, b) => ['attendee', 'no_show', 'speaker'].indexOf(a.segment) - ['attendee', 'no_show', 'speaker'].indexOf(b.segment));

const utm = (contacts.find(x => x.utm_campaign_postevent) || {}).utm_campaign_postevent || '';
const sample = (contacts.find(x => x.pe_recording_url) || {}).pe_recording_url || '';
return [{ json: {
  generated_at: new Date().toISOString(), run_id: run || null, sent_at: latest[0] ? latest[0].publishDate : null,
  utm_campaign: utm, sample_tracked_link: sample, segments,
  totals: segments.reduce((t, s) => ({ recipients: t.recipients + s.recipients, sent: t.sent + s.sent, delivered: t.delivered + s.delivered,
    opens: t.opens + s.opens, clicks: t.clicks + s.clicks, dropped: t.dropped + s.dropped }), { recipients: 0, sent: 0, delivered: 0, opens: 0, clicks: 0, dropped: 0 }),
  note: 'HubSpot developer test accounts only deliver to users of the account; other sends are logged as dropped. A paid Marketing Hub account delivers to everyone.',
} }];

// Hub · M3 page data: the latest content package in Google Drive (files, links, image previews, QA checks from the README).

const folder = ($('Find latest package').first().json.files || [])[0];
if (!folder) return [{ json: { found: false } }];
const files = ($('List package files').first().json.files || []).map(f => {
  const clean = String(f.name).replace(/^\[[^\]]+\]\s*/, '');
  const kind = /\.png$|\.jpg$/i.test(f.name) ? 'image' : /\.html$/i.test(f.name) ? 'html' : /skipped/.test(f.name) ? 'note' : 'doc';
  return { id: f.id, name: clean, kind, mime: f.mimeType, url: f.webViewLink, preview: kind === 'image' ? `hub-img?id=${f.id}` : null, created: f.createdTime };
}).sort((a, b) => a.name.localeCompare(b.name));

const readme = String($json.data || $json || '');
const checks = readme.split('\n').map(l => l.trim()).filter(l => /^[-*•]?\s*\**(PASS|CHECK)\**:/.test(l.replace(/^[-*•]\s*/, '')))
  .map(l => { const t = l.replace(/^[-*•]\s*/, '').replace(/\*\*/g, ''); return { pass: t.startsWith('PASS'), text: t.replace(/^(PASS|CHECK):\s*/, '') }; });
const counts = (readme.match(/Blog \d+ words[^\n]*/) || [''])[0];
const guard = (readme.match(/Insights [^\n]*verified[^\n]*/) || [''])[0];
const chapters = (readme.match(/AI chapters matched[^\n]*/) || [''])[0];

return [{ json: {
  found: true, generated_at: new Date().toISOString(),
  folder: { id: folder.id, name: folder.name, url: `https://drive.google.com/drive/folders/${folder.id}`, created: folder.createdTime },
  images: files.filter(f => f.kind === 'image'), docs: files.filter(f => f.kind !== 'image'),
  checks, counts, guard, chapters,
} }];

// Only serve images that belong to a content package (tagged file names), never any other Drive file.
if (!String($json.mimeType || '').startsWith('image/') || !String($json.name || '').startsWith('[')) throw new Error('Not a content-package image');
return [{ json: { id: $json.id } }];
